<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'

import { onIonViewDidEnter, useIonRouter } from '@ionic/vue'
import { storeToRefs } from 'pinia'
import CreateSekaiFooter from './CreateSekaiFooter.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import PencilIcon from '@/components/svg/PencilIcon.vue'
import VoiceItem from '@/components/items/VoiceItem.vue'
import CheckIconGreen from '@/components/svg/CheckIconGreen.vue'
import { universeService } from '@/services/universe'

interface Props {
  headerHeight: number
}

defineProps<Props>()

const createUniverseStore = useCreateUniverseStore()
const { generatedUniverse } = storeToRefs(createUniverseStore)
const router = useIonRouter()

const audio = ref<HTMLAudioElement | null>(null)
const playingVoiceId = ref(-1)
const playingVoiceCharacter = ref(-1)
const interval = ref<NodeJS.Timeout>()

onMounted(() => {
  interval.value = setInterval(() => {
    if (
      generatedUniverse.value?.chars?.filter(
        c => c?.charId && c?.complete !== true,
      )?.length === 0
    ) {
      clearInterval(interval.value)
    }
    else {
      createUniverseStore.refreshDraft()
    }
  }, 5000)
})

onUnmounted(() => clearInterval(interval.value))

onIonViewDidEnter(() => {})

async function play(id: number, url: string, characterId: number) {
  if (id === playingVoiceId.value && playingVoiceCharacter.value === characterId) {
    if (audio.value?.paused) {
      audio.value?.play()
    }
    else {
      audio.value?.pause()
    }
  }
  else {
    audio.value?.pause()
    audio.value = new Audio(url)
    audio.value.onplay = () => {
      playingVoiceId.value = id
      playingVoiceCharacter.value = characterId
    }
    audio.value.onended = () => {
      playingVoiceId.value = -1
      playingVoiceCharacter.value = -1
    }
    audio.value?.play()
  }
}

async function handleSelectUserChar(userCharId: number) {
  // if the userCharId is the same as the current userCharId, then set it to null

  if (createUniverseStore.generatedUniverse) {
    let updatedUserCharId = userCharId

    if (generatedUniverse?.value?.userCharId === userCharId) {
      updatedUserCharId = 0
    }
    try {
      await universeService.updateUniverseDraftById(
        createUniverseStore.generatedUniverse.universeId,
        {
          userCharId: updatedUserCharId,
        },
      )
      createUniverseStore.setUniverseDraft({
        ...createUniverseStore.generatedUniverse,
        userCharId: updatedUserCharId,
      })
    }
    catch (e) {
      console.error(e)
    }
  }
}
</script>

<template>
  <div class="flex flex-col justify-between h-full pb-unsafe-area">
    <div class="overflow-x-auto w-full h-full whitespace-nowrap my-4 flex-1">
      <div
        v-for="(character, index) in generatedUniverse?.chars?.filter(
          (u) => u.charId,
        )"
        :key="character.charId || index"
        class="inline-block w-full h-full py-3 px-4 ml-4 chapter relative"
      >
        <div
          class="pose h-full"
          :style="{
            backgroundImage: `url(${character?.pose?.original})`,
          }"
        />
        <div class="w-full h-full">
          <div
            class="relative flex justify-between items-center"
            style="z-index: 3"
          >
            <p class="title">
              {{ character.charName }}
            </p>
            <pencil-icon
              style="width: 20px; height: 20px"
              @click="
                () => {
                  createUniverseStore.setInEditCharacter({
                    charId: character.charId,
                    charName: character.charName,
                    charDescription: character.charDescription,
                    complete: character.complete,
                  });
                  router.push(`/character-setting/${character.charId}`);
                }
              "
            />
          </div>
          <div class="bottom w-full">
            <div
              class="mb-4"
              :class="[
                generatedUniverse?.userCharId === character.charId
                  ? 'option-select'
                  : 'option',
              ]"
              @click="handleSelectUserChar(character.charId)"
            >
              <check-icon-green
                v-if="generatedUniverse?.userCharId === character.charId"
              />
              {{
                generatedUniverse?.userCharId === character.charId
                  ? "Player character"
                  : "Set as player character"
              }}
            </div>
            <div class="desc mb-4">
              {{ character.charDescription }}
            </div>
            <voice-item
              :voice-id="character.voice || 0"
              :playing="playingVoiceId === character.voice && playingVoiceCharacter === character.charId"
              @click-play="(id, url) => play(id, url, character.charId)"
            />
          </div>
        </div>
      </div>
    </div>
    <create-sekai-footer
      :show-go-back="true"
      @on-next-click="createUniverseStore.nextStep()"
    />
  </div>
</template>

