<script setup lang="ts">
import { defineEmits, defineProps, onMounted, onUnmounted, ref } from 'vue'

import VuePictureCropper, { cropper } from 'vue-picture-cropper'

defineProps<{
  url: string
  show: boolean
}>()
const emits = defineEmits(['onSave', 'onClose'])

const width = ref<number>(360)

onMounted(() => {
  resize()
  window.addEventListener('resize', resize)
})

onUnmounted(() => {
  window.removeEventListener('resize', resize)
})

function resize() {
  let newWidth = window.innerWidth - 32
  if (newWidth > 360) {
    newWidth = 360
  }
  width.value = newWidth
}

async function onSaveCrop() {
  if (!cropper) {
    return
  }
  const base64 = cropper.getDataURL()
  emits('onSave', base64)
}
function ready() {
  console.log('Cropper is ready.')
}
</script>

<template>
  <ion-page v-if="show" class="container">
    <div class="w-full h-full bg-black">
      <vue-picture-cropper
        v-if="show" :box-style="{
          width: '100%',
          height: '100%',
          backgroundColor: '#333',
          margin: 'auto',
        }" :img="url" :options="{
          viewMode: 2,
          dragMode: 'crop',
          aspectRatio: 9 / 16,
        }" @ready="ready"
      />
      <ion-button fill="clear" class="absolute bottom-4 right-6 color-white" @click="onSaveCrop">
        Change
      </ion-button>
      <ion-button
        fill="clear" class="absolute bottom-4 left-6 color-white" @click="() => {
          $emit('onClose')
        }"
      >
        Cancel
      </ion-button>
    </div>
  </ion-page>
</template>

<style scoped>
.container {
  position: fixed;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  z-index: 999;
}
</style>
