<script setup lang="ts">
import { IonTextarea } from '@ionic/vue'
import { ref } from 'vue'
import CreateSekaiFooter from './CreateSekaiFooter.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import { universeService } from '@/services/universe'
import { eventService } from '@/services/event'
import LoadingComponent from '@/components/LoadingComponent.vue'

const createUniverseStore = useCreateUniverseStore()
const loading = ref(false)

async function onGoNext() {
  try {
    loading.value = true
    const eventDescription = createUniverseStore.basicSettingScenario
    const createdUniverse = await universeService.createUniverseDraft({
      whatIf: createUniverseStore.whatIf,
      background: createUniverseStore.basicSettingBackground,
      storyTellerStyle:
        createUniverseStore.eventsSuggestions[
          createUniverseStore.selectedEventSuggestion
        ].storyTellerStyle,
      firstEventSuggestions: createUniverseStore.eventsSuggestions,
    })
    createUniverseStore.setUniverseDraft(createdUniverse)
    await eventService.createEvent({
      universeId: createdUniverse.universeId,
      eventDescription,
      // 首个事件所以这里一定是0
      eventOrder: 0,
    })
    const latestUniverse = await universeService.getUniverseDraftById(
      createdUniverse.universeId,
    )
    createUniverseStore.setUniverseDraft(latestUniverse)
    createUniverseStore.nextStep()
  }
  catch (err) {
    console.error(err)
  }
  finally {
    loading.value = false
  }
}
</script>

<template>
  <loading-component v-if="loading" text="Generate Characters..." />
  <div v-else class="flex flex-col justify-between h-full">
    <div class="pb-20">
      <div class="card">
        <div class="title">
          Where does this story take place?
        </div>
        <ion-textarea
          id="user_char_textarea"
          v-model="createUniverseStore.basicSettingBackground"
          class="mt-2 text-area"
          placeholder="Example:
Mondstadt Academy, after school hours, modern school setting."
          autocomplete="on"
          autocorrect="on"
          autocapitalize="on"
          :rows="3"
          :auto-grow="true"
          :error-text="$t('createUniversePage.isRequired')"
          :maxlength="100"
          :counter="true"
        />
        <div class="desc">
          This typically includes the story’s location, time, occasion, and
          universe setting.
        </div>
      </div>
      <div class="card">
        <div class="title">
          Starting Scenario
        </div>
        <ion-textarea
          id="user_char_textarea"
          v-model="createUniverseStore.basicSettingScenario"
          class="mt-2 text-area"
          placeholder="Example:
Hutao bursts into Ganyu's classroom, slamming the door open and startling Aether and Ganyu. She waves Aether's report card, demanding an explanation for his abysmal grades. This scenario includes characters: Hutao, Aether, Ganyu"
          autocomplete="on"
          autocorrect="on"
          autocapitalize="on"
          :rows="8"
          :auto-grow="true"
          :error-text="$t('createUniversePage.isRequired')"
          :maxlength="1000"
          :counter="true"
        />
      </div>
    </div>
    <div class="fixed bottom-unsafe-area left-0 w-full">
      <create-sekai-footer
        :show-go-back="true"
        :disable-go-next="
          createUniverseStore.basicSettingBackground?.length === 0
            || createUniverseStore.basicSettingScenario?.length === 0
        "
        @on-next-click="onGoNext"
      />
    </div>
  </div>
</template>

