<script setup lang='ts'>
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { IonPage } from '@ionic/vue'
import SekaiMainPage from '../SekaiMainPage.vue'
import CreatePovTitle from './CreatePovTitle.vue'
import { universeService } from '@/services/universe'
import type { Chat } from '@/types'
import IconButton from '@/components/IconButton.vue'
import { generateChatFromReturnedUniverse } from '@/utils/generateChatFromUniverse'
import { useChatsStore } from '@/store/chats'
import { useBgm } from '@/composables/useBgm'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import BgmSelect from '@/components/BgmSelect.vue'
import BackgroundSelect from '@/components/BackgroundSelect.vue'
import TextTitleIcon from '@/components/svg/TextTitleIcon.vue'
import FilterIcon from '@/components/svg/FilterIcon.vue'
import { useTextTitleStore } from '@/store/textTitleStore'
import MusicIcon from '@/components/svg/MusicIcon.vue'
import LoadingComponent from '@/components/LoadingComponent.vue'

interface Emits {
  (e: 'onEditTitle', edit: boolean): void
}

const emit = defineEmits<Emits>()

const chat = ref<Chat | undefined>()
const sekaiRef = ref<InstanceType<typeof SekaiMainPage> | null>(null)
const chatStore = useChatsStore()
const createUniverseStore = useCreateUniverseStore()
const textTitleStore = useTextTitleStore()
const bgm = useBgm()

const isShowBgmModal = ref(false)
const isShowBgModal = ref(false)
const isShowTextTitle = ref(false)

const isEdittingTitle = ref(false)
const isShowDecorations = ref(true)
const showPovTitle = ref(true)

watch(
  () => isShowTextTitle.value,
  (val) => {
    emit('onEditTitle', val)
  },
)

// use the universeId to fetch the universe details
onMounted(async () => {
  if (!createUniverseStore.generatedUniverse) {
    return
  }

  const universe = await universeService.getUniverseDraftById(
    createUniverseStore.generatedUniverse?.universeId,
  )
  chat.value = generateChatFromReturnedUniverse(universe)
  chatStore.setCurrentChatId(chat.value.chatId)

  bgm.playBgm(chat.value.bgmUrl)
})

onUnmounted(() => {
  bgm.stopBgm()
})

function onToggleEditMode(editting: boolean) {
  emit('onEditTitle', editting)
  if (sekaiRef?.value) {
    if (editting) {
      sekaiRef.value.pause()
    }
    else {
      sekaiRef.value.resume()
    }
  }
}

function onOpenTitleEdit(init: boolean = false) {
  isShowTextTitle.value = true
  if (sekaiRef?.value) {
    sekaiRef.value.pause()
  }
  if (init) {
    textTitleStore.initTitle()
  }
}

function onHideTitleEdit(isDelete: boolean = false) {
  emit('onEditTitle', false)
  if (isDelete) {
    isShowTextTitle.value = false
    textTitleStore.deleteTitle()
  }
  else {
    if (sekaiRef?.value) {
      sekaiRef.value.resume()
    }
  }
}

function updateSekaiBg(url: string) {
  if (sekaiRef?.value) {
    sekaiRef.value.updateBgImg(url)
  }
}

defineExpose({
  resetSekai: () => {
    sekaiRef.value?.reset()
  },
})
</script>

<template>
  <ion-page>
    <loading-component v-if="!chat" />
    <div v-else class="sekai-wrapper">
      <sekai-main-page
        ref="sekaiRef"
        :chat="chat"
        :next-chat="undefined"
        :is-loading="false"
        :is-preview="true"
        :active="!isShowBgModal && !isShowBgmModal"
        @on-toggle-decorations="
          (val) => {
            isShowDecorations = val
            showPovTitle = val
          }
        "
      />
    </div>
    <div>
      <!-- 注意点击事件冲突 -->
      <div
        v-if="chat?.bgmName && isShowDecorations"
        class="bgm absolute mt-unsafe-area top-20 left-1/2 -translate-x-1/2 text-nowrap z-101"
        @click="() => {
          //pause bgm
          bgm.stopBgm()
          isShowBgmModal = true
        }"
      >
        <music-icon />
        {{ chat?.bgmName.length > 20 ? `${chat?.bgmName.slice(0, 25)}...` : chat?.bgmName }}
      </div>
      <bgm-select
        :is-open="isShowBgmModal"
        @close="() => {
          isShowBgmModal = false
          bgm.resumeBgm()
        }"
        @bgm-select="async (newBgm) => {
          if (newBgm) {
            bgm.playBgm(newBgm.url)
            //update the bgm name for the chat
            if (chat) {
              chat.bgmName = newBgm.name
            }
            isShowBgModal = false
            try {
              await universeService.updateUniverseDraftById(
                createUniverseStore.generatedUniverse?.universeId!,
                {
                  bgm: { id: newBgm.id },
                },
              )
            }
            catch (err) {
              console.error(err)

            }
          }
        }"
      />
    </div>

    <div>
      <!-- 注意点击事件冲突 -->
      <icon-button
        v-if="!isEdittingTitle && isShowDecorations"
        class="absolute top-20 right-2 z-101"
        :style="{ top: 'calc(3.5rem + 54px + env(safe-area-inset-top))' }"
        @click="
          () => {
            isShowBgModal = true
          }
        "
      >
        <filter-icon />
      </icon-button>
      <background-select
        :is-open="isShowBgModal"
        @update-bg="(bgUrl) => {
          updateSekaiBg(bgUrl)
        }"
        @close="isShowBgModal = false"
      />
    </div>

    <icon-button
      v-if="!isShowTextTitle && isShowDecorations"
      class="absolute right-2 z-101"
      :style="{ top: 'calc(7rem + 54px + env(safe-area-inset-top))' }"
      @click="
        () => {
          onOpenTitleEdit(true)
        }
      "
    >
      <text-title-icon />
    </icon-button>
    <create-pov-title
      v-if="isShowTextTitle"
      :show="showPovTitle"
      @on-edit-title="
        (val) => {
          isEdittingTitle = val
          onToggleEditMode(val)
        }
      "
      @on-delete-title="() => onHideTitleEdit(true)"
    />
  </ion-page>
</template>

