<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { characterService } from '@/services/character'
import type { CharacterVoiceModel } from '@/types/character'
import SoundWaveIcon from '@/components/svg/SoundWaveIcon.vue'
import SoundSpeakerIcon from '@/components/svg/SoundSpeakerIcon.vue'

const props = defineProps<Props>()
const emits = defineEmits(['clickPlay'])

interface Props {
  voiceId: number
  playing?: boolean
}

const voice = ref<CharacterVoiceModel | null>(null)
// Get the voice information
async function fetchCharacterVoice() {
  // fetch the voice information from the server
  // and save it to the store
  try {
    if (props.voiceId) {
      const res = await characterService.fetchVoiceById(props.voiceId)
      console.log(res)
      if (res) {
        voice.value = res
      }
    }
  }
  catch (err) {
    console.error(err)
  }
}

onMounted(() => {
  fetchCharacterVoice()
})

watch(
  () => props.voiceId,
  (newVoiceId) => {
    if (newVoiceId) {
      fetchCharacterVoice()
    }
  },
)

async function play() {
  emits('clickPlay', props.voiceId, voice.value?.sampleUrl)
}
</script>

<template>
  <div class="item">
    <div class="flex flex-1 justify-between items-center">
      <div class="flex-1 title">
        {{ voice?.displayName }}
      </div>
      <div
        class="sound-play"
        :style="playing
          ? 'background-color: #00F4FF'
          : ''
        "
        @click="play"
      >
        <sound-wave-icon v-if="playing" />
        <sound-speaker-icon v-else />
        {{ voice?.duration }}”
      </div>
    </div>
  </div>
</template>

