<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { AxiosProgressEvent } from 'axios'
import type { UploaderAfterRead } from 'vant/lib/uploader/types'
import { loadingController } from '@ionic/vue'
import { Tab, Tabs, Uploader, Circle as VanCircle } from 'vant'
import BgmItem from '@/components/BgmItem.vue'
import DeleteIcon from '@/components/svg/DeleteIcon.vue'
import ClearIcon from '@/components/svg/ClearIcon.vue'
import type { IBGMItem } from '@/types/audio'
import type { GetBGMListResult } from '@/services/universe'
import { universeService } from '@/services/universe'
import AddIconRound from '@/components/svg/AddIconRound.vue'

interface Props {
  isOpen: boolean
}

defineProps<Props>()
const emits = defineEmits<Emits>()

interface Emits {
  (e: 'bgmSelect', bgm: IBGMItem | null): void
  (e: 'close'): void
}

const presentingElement = ref()
const modal = ref()
const page = ref()
const bgmList = ref<GetBGMListResult>({})
const active = ref(0)
const tagList = computed(() => Object.keys(bgmList.value))
const keyword = ref('')
const uploading = ref(false)
const uploadProgress = ref(0)
const fileName = ref('')
const uploadedBGM = ref<IBGMItem | null>(null)
const activeBgm = ref(-1)
const audio = ref<HTMLAudioElement | null>(null)
const currentChapterId = ref(-1)

const allList = computed(() => tagList.value.flatMap(tag => bgmList.value[tag]))
const filteredList = computed(() => allList.value.filter(bgm => bgm?.name?.toLowerCase()?.includes(keyword?.value?.trim()?.toLowerCase())))

const playState = ref(false)

async function play(src: string) {
  if (playState.value && audio.value?.src === src) {
    await audio.value?.pause()
  }
  else {
    if (playState.value) {
      await audio.value?.pause()
    }
    audio.value = new Audio(src)
    audio.value.onplay = () => {
      playState.value = true
      console.log('playState true')
    }
    audio.value.onpause = () => {
      playState.value = false
      console.log('playState false')
    }
    await audio.value?.play()
  }
}
async function loadBgmList() {
  try {
    const res = await universeService.getBGMList()
    bgmList.value = res
    console.log(res)
  }
  catch (error) {

  }
}

onMounted(() => {
  presentingElement.value = page.value
  loadBgmList()
})

function onUploadProgress(e: AxiosProgressEvent) {
  uploadProgress.value = (e?.progress || 0) * 100
}

const afterRead: UploaderAfterRead = async (file: any) => {
  // 此时可以自行将文件上传至服务器
  if (!file?.file.name) {
    return
  }
  const t = new Audio(file?.objectUrl)
  t.onloadedmetadata = async () => {
    console.log(t, t.duration)
    const loading = await loadingController.create({
      duration: 5000,
    })
    loading.present()
    const res = await universeService.generateBGMPresignedUrl(file.file.name)
    loading.dismiss()
    if (res.presignedUrl) {
      fileName.value = file.file.name
      uploading.value = true
      try {
        const upload = await universeService.uploadBGM(res.presignedUrl, file.file, onUploadProgress)
        console.log(upload)
        const bgmInfo = {
          url: res.s3Prefix,
          name: file.file.name,
          tags: [],
          public: false,
          duration: Math.floor(t.duration),
        }
        const bgm = await universeService.createBGM(bgmInfo)
        uploadedBGM.value = bgm
        uploading.value = false
      }
      catch (error) {
        console.error(error)
        uploading.value = false
      }
    }
  }
}

function handleClickBgm(id: number) {
  if (activeBgm.value === id) {
    activeBgm.value = -1
  }
  else {
    activeBgm.value = id
  }
}

function handleCloseModal() {
  audio.value?.load()
  playState.value = false
  activeBgm.value = -1
  emits('close')
}

function handleSelectBgm(bgm: IBGMItem | null) {
  audio.value?.load()
  playState.value = false
  activeBgm.value = -1
  currentChapterId.value = -1
  emits('bgmSelect', bgm)
  emits('close')
}
</script>

<template>
  <ion-modal
    ref="modal" mode="ios" :is-open="isOpen" :presenting-element="presentingElement" @ion-modal-did-dismiss="handleCloseModal"
  >
    <ion-header>
      <ion-toolbar>
        <ion-title>BGM</ion-title>
        <ion-buttons slot="start">
          <ion-button color="light" @click="handleCloseModal">
            Cancel
          </ion-button>
        </ion-buttons>
      </ion-toolbar>
    </ion-header>
    <ion-content>
      <ion-searchbar v-model="keyword" class="px-4" />
      <div v-if="uploading === false && uploadedBGM" class="upload-card flex items-center justify-between mx-4 p-2 my-2">
        <bgm-item
          class="m-0"
          :item="uploadedBGM"
          :playing="activeBgm === uploadedBGM?.id && playState"
          @click-play="() => {
            play(uploadedBGM?.url || '')
            handleClickBgm(uploadedBGM?.id || -1)
          }"
        />
        <div class="flex items-center gap-3 h-8 overflow-hidden mr-2">
          <delete-icon @click="() => uploadedBGM = null" />
          <ion-button size="small" color="black" fill="clear" style="background-color: #00F4FF; border-radius: 100px; height: 32px;" @click="handleSelectBgm(uploadedBGM)">
            Select
          </ion-button>
        </div>
      </div>
      <uploader v-else-if="keyword === '' && uploading === false" class="w-full" accept="*" :after-read="afterRead">
        <div class="upload-card flex items-center justify-between p-2 mx-4 my-2">
          <div class="flex items-center gap-2 overflow-hidden">
            <div class="upload-cover" :style="uploading ? 'unset' : 'background-color: rgba(255, 255, 255, 0.16);'">
              <add-icon-round v-if="uploading === false" />
              <van-circle v-else size="32" :current-rate="uploadProgress" color="#05F0FF" />
            </div>
            <div v-if="uploading === false && !uploadedBGM" class="flex-1 truncate">
              {{ 'Upload your sound file' }}
            </div>
            <div v-else class="flex-1 truncate">
              Uploading <span class="font-bold">{{ fileName }}</span>
            </div>
          </div>
          <clear-icon v-if="uploading" @click="uploading = false" />
        </div>
      </uploader>
      <div v-else-if="keyword === ''" class="upload-card flex items-center justify-between p-2 mx-4 my-2">
        <div class="flex items-center gap-2 overflow-hidden">
          <div class="upload-cover" :style="uploading ? 'unset' : 'background-color: rgba(255, 255, 255, 0.16);'">
            <add-icon-round v-if="uploading === false" />
            <van-circle v-else size="32" :current-rate="uploadProgress" color="#05F0FF" />
          </div>
          <div v-if="uploading === false && !uploadedBGM" class="flex-1 truncate">
            {{ 'Upload your sound file' }}
          </div>
          <div v-else class="flex-1 truncate">
            Uploading <span class="font-bold">{{ fileName }}</span>
          </div>
        </div>
        <clear-icon v-if="uploading" style="min-width: 24px;" @click="uploading = false" />
      </div>
      <tabs v-if="keyword === ''" v-model:active="active" class="tabs">
        <tab v-for="tag in tagList" :key="tag" :title="tag">
          <div v-for="bgm in bgmList[tag]" :key="bgm.id" class="flex items-center justify-between px-4 py-2 mt-2">
            <bgm-item
              :item="bgm"
              :playing="activeBgm === bgm.id && playState"
              @click-play="(id) => {
                handleClickBgm(id)
                play(bgm.url)
              }"
            />
            <ion-button v-if="activeBgm === bgm.id" size="small" color="black" fill="clear" style="background-color: #00F4FF; border-radius: 100px; height: 32px;" @click="handleSelectBgm(bgm)">
              Select
            </ion-button>
          </div>
        </tab>
      </tabs>
      <div v-for="bgm in filteredList" v-else-if="filteredList.length > 0" :key="bgm?.id" class="flex items-center justify-between px-4 py-2 mt-2">
        <bgm-item
          :item="bgm"
          :playing="activeBgm === bgm.id && playState"
          @click-play="(id) => {
            handleClickBgm(id)
            play(bgm.url)
          }"
        />
        <ion-button v-if="activeBgm === bgm.id" size="small" color="black" fill="clear" style="background-color: #00F4FF; border-radius: 100px; height: 32px;" @click="handleSelectBgm(bgm)">
          Select
        </ion-button>
      </div>
    </ion-content>
  </ion-modal>
</template>

