<script setup lang="ts">
import { IonButton, IonContent, IonTextarea, IonToast } from '@ionic/vue'
import { ref } from 'vue'
import { Uploader } from 'vant'

import type { UploaderAfterRead } from 'vant/lib/uploader/types'
import { storeToRefs } from 'pinia'
import CloseIcon from './svg/CloseIcon.vue'
import CheckedIconCircleFill from './svg/CheckedIconCircleFill.vue'
import CheckIconCircleEmpty from './svg/CheckIconCircleEmpty.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import { useBackgroundStore } from '@/store/backgroundStore'
import CardContainer from '@/components/CardContainer.vue'
import UploadImageIcon from '@/components/svg/UploadImageIcon.vue'
import { characterService } from '@/services/character'
import ImageCroper from '@/components/ImageCroper.vue'

// 加载几个默认模版图片
import { eventService } from '@/services/event'
import { base64ToFile } from '@/utils/stringUtil'
import LoadingLottie from '@/components/LoadingLottie.vue'

interface Props {
  isOpen: boolean
}

interface Emits {
  (e: 'close'): void
  (e: 'updateBg', url: string): void
}

type SelectType = 'gen' | 'import'

defineProps<Props>()
const emits = defineEmits<Emits>()

const presentingElement = ref()
const modal = ref()
const createUniverseStore = useCreateUniverseStore()
const backgroundStore = useBackgroundStore()
// store the uploaded avatar preview to the store
const { generatedUniverse } = storeToRefs(createUniverseStore)

const selectType = ref<SelectType>('gen')
const isLoading = ref(false)
const toastIsOpen = ref(false)
const toastMessage = ref('')
// ion content dom element
const wrapper = ref<typeof IonContent>()
const showCroper = ref(false)
const cropUrl = ref('')
const selectedFile = ref<File>()
// const currEdit = ref<SelectType>('gen')

// convert the id to number
const eventId = generatedUniverse.value?.events?.[0]?.eventId
const event = generatedUniverse.value?.events?.[0]
const generatedImage = ref<string>(
  backgroundStore.generatedBackground?.presignedUrl || event?.gifUrl || '',
)
const generatedImageS3Url = ref<string | null>(
  backgroundStore.generatedBackground?.s3Prefix || null,
)
console.debug(generatedImage.value)
const uploadedImage = ref<string | null>(
  backgroundStore.uploadedBackgroundPreview?.presignedUrl || null,
)
const uploadedImageS3Url = ref<string | null>(
  backgroundStore.uploadedBackgroundPreview?.s3Prefix || null,
)
const imageUploading = ref(false)

// the content of the prompt
const prompt = ref(event?.backgroundKeywords || '')

// Handle generate the avatar when everything is ready
async function handleGenerate() {
  // scroll the page to the top
  if (wrapper.value) {
    wrapper.value.$el.scrollToTop()
  }

  isLoading.value = true
  try {
    // update the character avatar
    const res = await eventService.generateEventBackgroundImage(
      {
        eventId: eventId!,
        backgroundKeywords: prompt.value,
      },
      {
        timeout: 1000 * 60 * 5,
      },
    )
    console.debug(res)
    generatedImage.value = res.presignedUrl
    generatedImageS3Url.value = res.s3Prefix
    isLoading.value = false
  }
  catch (error) {
    console.log(error)
    isLoading.value = false
  }
}

async function handleSave() {
  console.debug('[handleSave] prompt')
  console.debug(
    `generatedImage: ${generatedImage.value} S3: ${generatedImageS3Url.value}`,
  )
  console.debug(
    `uploadedImage: ${uploadedImage.value} S3: ${uploadedImageS3Url.value}`,
  )
  // 已签过名的用于展示
  const newImageUrl
    = selectType.value === 'gen' ? generatedImage.value : uploadedImage.value
  const newSekai = {
    ...createUniverseStore.generatedUniverse!,
    events: [
      {
        ...event!,
        gifUrl: newImageUrl || '',
        backgroundKeywords: prompt.value,
      },
    ],
  }
  createUniverseStore.setUniverseDraft(newSekai)
  const newBgS3
    = (selectType.value === 'gen'
      ? generatedImageS3Url.value
      : uploadedImageS3Url.value) || ''
  if (newBgS3 === '') {
    toastMessage.value
      = selectType.value === 'gen'
        ? 'Please generate a image'
        : 'Please upload a image'
    toastIsOpen.value = true
    return
  }

  const res = await eventService.updateEvent(eventId!, {
    // S3链接，用于数据库储存
    gifUrl: newBgS3,
  })
  console.debug(res)
  emits('updateBg', newImageUrl || '')
  emits('close')
}

function handleTriggerEdit(type: SelectType) {
  showCroper.value = true
  cropUrl.value
    = type === 'gen'
      ? generatedImage.value || ''
      : URL.createObjectURL(selectedFile.value!)
}

async function handleSaveCrop(data: string) {
  uploadedImage.value = data
  showCroper.value = false
  if (uploadedImage.value && selectedFile.value) {
    try {
      imageUploading.value = true
      const tempFile = base64ToFile(
        uploadedImage.value,
        selectedFile.value?.name,
        selectedFile.value?.type,
      )
      const res = await characterService.presignBackgroundUrl(tempFile?.name)
      await characterService.uploadImage(res.presignedUrl, tempFile!)
      console.debug('finished uploading')
      uploadedImageS3Url.value = res.s3Prefix
      uploadedImage.value = res.presignedUrl
      // 用于下次打开展示
      backgroundStore.setUploadedBackgroundPreview({
        presignedUrl: res.presignedUrl,
        s3Prefix: res.s3Prefix,
      })
    }
    catch (err) {
      console.error(err)
      toastMessage.value = 'Failed to upload image'
      toastIsOpen.value = true
      cropUrl.value = ''
    }
    finally {
      imageUploading.value = false
    }
  }
}

const afterRead: UploaderAfterRead = async (file: any) => {
  // 此时可以自行将文件上传至服务器
  if (!file?.file.name) {
    return
  }

  selectedFile.value = file?.file
  handleTriggerEdit('import')
}

function handleCloseModal() {
  emits('close')
}
</script>

<template>
  <ion-modal
    ref="modal"
    mode="ios"
    :is-open="isOpen"
    :presenting-element="presentingElement"
    @ion-modal-did-dismiss="handleCloseModal"
  >
    <ion-header>
      <ion-toolbar>
        <ion-title>Sekai Media</ion-title>
        <ion-buttons slot="start">
          <ion-button color="light" @click="handleCloseModal">
            <close-icon />
          </ion-button>
        </ion-buttons>
      </ion-toolbar>
    </ion-header>
    <ion-toast
      :is-open="toastIsOpen"
      :message="toastMessage"
      :duration="3000"
      position="middle"
      class="custom-toast"
      @did-dismiss="() => (toastIsOpen = false)"
    />
    <ion-content ref="wrapper" class="ion-padding">
      <loading-lottie v-if="isLoading" class="text-center" />
      <signed-img
        v-else
        class="block m-auto mt-2"
        :style="{ width: '180px' }"
        :src="generatedImage || ''"
      />
      <card-container>
        <p
          class="flex-shrink-0 text-4 fw-500 leading-6 text-nowrap flex items-center gap-2"
          @click="selectType = 'gen'"
        >
          <checked-icon-circle-fill v-if="selectType === 'gen'" />
          <check-icon-circle-empty v-else />
          Generated image
        </p>
        <p class="text-on-bg-3">
          Edit keywords to update Sekai’s background image
        </p>
        <div
          v-if="generatedImage"
          class="mt-4 relative m-auto overflow-hidden rounded-2xl"
          :style="{ width: '154px' }"
        >
          <img :style="{ width: '154px' }" :src="generatedImage">
          <ion-button
            size="small"
            shape="round"
            class="w-10 absolute top-1 left-1 secondary-button"
            @click="() => handleTriggerEdit('gen')"
          >
            Edit
          </ion-button>
          <ion-button
            v-if="generatedImage"
            size="small"
            shape="round"
            class="w-14 absolute top-1 right-1 secondary-button"
            @click="
              () => {
                generatedImage = '';
                generatedImageS3Url = null;
                backgroundStore.setGeneratedBackground(undefined);
              }
            "
          >
            Delete
          </ion-button>
        </div>
        <ion-textarea
          v-model="prompt"
          class="mt-4 text-area"
          placeholder="Enter description"
          autocomplete="on"
          autocorrect="on"
          autocapitalize="on"
          :rows="3"
          :auto-grow="true"
          :error-text="$t('createUniversePage.isRequired')"
          :maxlength="1200"
        />
        <ion-button
          shape="round"
          class="w-full mt-2 secondary-button"
          :disabled="isLoading"
          @click="handleGenerate"
        >
          {{
            isLoading
              ? "Generating"
              : generatedImage !== ""
                ? "Regenerate"
                : "Generate"
          }}
        </ion-button>
      </card-container>
      <card-container>
        <p
          class="flex-shrink-0 text-4 fw-500 leading-6 text-nowrap flex items-center gap-2"
          @click="selectType = 'import'"
        >
          <checked-icon-circle-fill v-if="selectType === 'import'" />
          <check-icon-circle-empty v-else />
          Import Image
        </p>
        <p class="text-on-bg-3">
          You can import your image to set background
        </p>
        <div class="flex justify-center">
          <div
            v-if="uploadedImage"
            class="mt-4 relative m-auto overflow-hidden rounded-2xl"
            :style="{ width: '154px' }"
          >
            <div
              v-if="imageUploading"
              class="rd-4 px-4 py-2 flex justify-center items-center loading-wrapper"
              :style="{ width: '154px', height: '200px' }"
            >
              <loading-lottie />
            </div>
            <img v-else :style="{ width: '154px' }" :src="uploadedImage">
            <ion-button
              size="small"
              shape="round"
              class="w-10 absolute top-1 left-1 secondary-button"
              @click="() => handleTriggerEdit('import')"
            >
              Edit
            </ion-button>
            <ion-button
              v-if="uploadedImage"
              size="small"
              shape="round"
              class="w-14 absolute top-1 right-1 secondary-button"
              @click="
                () => {
                  uploadedImage = null;
                  uploadedImageS3Url = null;
                  selectedFile = undefined;
                  backgroundStore.setUploadedBackgroundPreview(undefined);
                }
              "
            >
              Delete
            </ion-button>
          </div>
          <uploader
            v-else
            class="flex-1 relative mt-4"
            :style="{ width: uploadedImage != null ? '154px' : 'auto' }"
            :after-read="afterRead"
          >
            <div
              class="w-full px-4 py-1 upload-img-btn flex justify-center items-center"
            >
              <upload-image-icon class="mr-2" />
              Import Image
            </div>
          </uploader>
        </div>
      </card-container>
      <div :style="{ height: '160px' }" />
      <div slot="fixed" class="px-4 w-full bottom-0 pb-unsafe-area">
        <button
          shape="round"
          class="w-full btn-primary"
          :disabled="isLoading"
          @click="handleSave"
        >
          Set Background
        </button>
      </div>
      <image-croper
        slot="fixed"
        :show="showCroper"
        :url="cropUrl"
        @on-close="showCroper = false"
        @on-save="handleSaveCrop"
      />
    </ion-content>
  </ion-modal>
</template>

