<script setup lang="ts">
import { IonContent, IonPage } from '@ionic/vue'
import { ref, watch } from 'vue'
import { useElementSize } from '@vueuse/core'
import { storeToRefs } from 'pinia'
import { showConfirmDialog } from 'vant'
import CreateSekaiHeader from './CreateSekaiHeader.vue'
import ConfigurePage from './CreateNewSekai.vue'
import CharacterPage from './CharacterPage.vue'
import BasicSettingsPage from './BasicSettingsPage.vue'
import StartScenarioPage from './StartScenarioPage.vue'
import PreviewSekai from './PreviewSekai.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import { universeService } from '@/services/universe'
import { useUserStore } from '@/store/user'
import LoadingComponent from '@/components/LoadingComponent.vue'

const headerElRef = ref<HTMLElement | null>(null)
const { height: headerHeight } = useElementSize(headerElRef)
const createUniverseStore = useCreateUniverseStore()
const userStore = useUserStore()
const { createStep, creatingState } = storeToRefs(createUniverseStore)
const previewSekaiRef = ref<typeof PreviewSekai | null>(null)
function onResetSekai() {
  if (previewSekaiRef.value) {
    previewSekaiRef.value.resetSekai()
  }
}

const isShowHeader = ref(true)

watch(
  () => userStore.user,
  async (val) => {
    if (val) {
      try {
        const draft = await universeService.getMostRecentUniverseDraft()
        // TODO: 弹窗
        if (draft) {
          showConfirmDialog({
            title: 'Draft restore',
            message:
              'Found a draft, do you want to continue from your last edit?',
            confirmButtonText: 'Confirm',
            cancelButtonText: 'Cancel',
            confirmButtonColor: '#fbe996',
          })
            .then(() => {
              createUniverseStore.setUniverseDraft(draft)
              createUniverseStore.setCreateStep(3)
            })
            .catch(() => {
              // on cancel
            })
        }
      }
      catch (err) {
        console.error(err)
      }
    }
  },
)
</script>

<template>
  <ion-page>
    <create-sekai-header v-show="isShowHeader" ref="headerElRef" @on-reset-sekai="onResetSekai" />
    <div v-if="createStep < 4" class="relative block pb-14 pt-unsafe-area" />
    <ion-content>
      <configure-page v-if="createStep === 0" />
      <start-scenario-page v-if="createStep === 1" />
      <basic-settings-page v-if="createStep === 2" />
      <character-page v-if="createStep === 3" :header-height="headerHeight" />
      <preview-sekai
        v-if="createStep === 4" ref="previewSekaiRef" @on-edit-title="
          (val) => {
            isShowHeader = !val;
          }
        "
      />
      <loading-component v-if="creatingState === 'waitRes'" text="The chatting history in preview will be discarded" />
    </ion-content>
  </ion-page>
</template>
